import React, { useState } from 'react';
import { DUMMY_ORDERS } from '../../data/orders';
import { getCareGuide } from '../../data/careGuides';
import './Notifications.css';

const Notifications = () => {
  const latestOrder = DUMMY_ORDERS[0];
  const [expandedGuides, setExpandedGuides] = useState({});

  const toggleGuide = (plantId) => {
    setExpandedGuides(prevState => ({
      ...prevState,
      [plantId]: !prevState[plantId],
    }));
  };

  return (
    <div className="notifications-page">
      <h1 className="notifications-title">My Plant Care Guide</h1>
      <div className="care-guide-section">
        {latestOrder.items.map(item => {
          const careGuide = getCareGuide(item.id);
          const isExpanded = expandedGuides[item.id];

          return (
            <div key={item.id} className="plant-care-guide">
              <h2>{item.name}</h2>
              <div className="timeline">
                <div className="timeline-item">
                  <div className="timeline-dot"></div>
                  <div className="timeline-content">
                    <p className="timeline-day">{careGuide[0].split(':')[0]}</p>
                    <p className="timeline-step">{careGuide[0].split(':')[1]}</p>
                  </div>
                </div>
                {isExpanded && careGuide.slice(1).map((step, index) => (
                  <div key={index} className="timeline-item">
                    <div className="timeline-dot"></div>
                    <div className="timeline-content">
                      <p className="timeline-day">{step.split(':')[0]}</p>
                      <p className="timeline-step">{step.split(':')[1]}</p>
                    </div>
                  </div>
                ))}
              </div>
              <button className="toggle-guide-btn" onClick={() => toggleGuide(item.id)}>
                {isExpanded ? 'Show less' : 'Show more'}
              </button>
            </div>
          );
        })}
      </div>

      <h1 className="notifications-title">Plant Care Guides</h1>
      <div className="guidelines-grid">
        <div className="guideline-card">
          <h2>Watering</h2>
          <p>Learn the best practices for watering your plants to keep them healthy. Most plants prefer to be watered when the top inch of soil is dry. Overwatering can lead to root rot, so it's important to check the soil moisture before watering.</p>
        </div>
        <div className="guideline-card">
          <h2>Lighting</h2>
          <p>Understand the light requirements for different types of plants. Most houseplants prefer bright, indirect light. Some plants, like succulents, need direct sunlight, while others, like ferns, can tolerate low light.</p>
        </div>
        <div className="guideline-card">
          <h2>Soil and Potting</h2>
          <p>Get tips on choosing the right soil and pot for your plants. A well-draining soil is essential for most plants. Make sure the pot has drainage holes to allow excess water to escape.</p>
        </div>
        <div className="guideline-card">
          <h2>Fertilizing</h2>
          <p>Find out how to provide your plants with the nutrients they need. Most plants benefit from regular fertilizing during the growing season. Use a balanced fertilizer and follow the instructions on the package.</p>
        </div>
        <div className="guideline-card">
          <h2>Pest Control</h2>
          <p>Learn how to identify and deal with common plant pests. Inspect your plants regularly for pests like spider mites, mealybugs, and aphids. Treat any infestations promptly with insecticidal soap or neem oil.</p>
        </div>
      </div>
    </div>
  );
};

export default Notifications;
